    def __init__(self):
        self._rolls = []
        self._frame = 0
        self._frame_rolls = []
        self._pins_remaining = 10
        self._complete = False

    def roll(self, pins):
        if self._complete:
            raise ValueError("Cannot roll after game is over")
        if not isinstance(pins, int) or isinstance(pins, bool):
            raise ValueError("Pin count must be an integer")
        if pins < 0:
            raise ValueError("Negative roll is invalid")
        if pins > self._pins_remaining:
            raise ValueError("Pin count exceeds pins on the lane")

        self._rolls.append(pins)
        self._frame_rolls.append(pins)
        self._pins_remaining -= pins

        if self._frame < 9:
            if pins == 10 or len(self._frame_rolls) == 2:
                self._frame += 1
                self._frame_rolls = []
                self._pins_remaining = 10
        else:
            # Only a strike or spare in the tenth frame earns fill balls.
            if len(self._frame_rolls) == 3:
                self._complete = True
            elif len(self._frame_rolls) == 2:
                self._complete = sum(self._frame_rolls) < 10

            # Fill balls use a fresh rack only after all pins are cleared.
            if self._pins_remaining == 0:
                self._pins_remaining = 10

    def score(self):
        if not self._complete:
            raise ValueError("Score cannot be taken until the end of the game")

        total = 0
        index = 0
        for _ in range(10):
            if self._rolls[index] == 10:
                total += sum(self._rolls[index:index + 3])
                index += 1
            elif self._rolls[index] + self._rolls[index + 1] == 10:
                total += sum(self._rolls[index:index + 3])
                index += 2
            else:
                total += sum(self._rolls[index:index + 2])
                index += 2
        return total
