<script>
const $ = id => document.getElementById(id);
let frames, current, remaining, complete;
function reset() {
  frames = Array.from({length:10}, () => []);
  current = 0; remaining = 10; complete = false;
  $('pins').value = '0';
  $('message').textContent = 'Ready for your first roll.';
  render();
}
function totals() {
  const rolls = frames.flat();
  let index = 0, total = 0;
  return frames.map((frame, i) => {
    const count = frame[0] === 10 ? 1 : 2;
    const needed = frame[0] === 10 || (frame.length >= 2 && frame[0] + frame[1] === 10) ? 3 : 2;
    let result = null;
    if (i === 9) {
      if (complete) { total += frame.reduce((a,b) => a+b,0); result = total; }
    } else if (frame.length >= count && rolls.length >= index + needed) {
      total += rolls.slice(index,index + needed).reduce((a,b) => a+b,0);
      result = total;
    }
    index += frame.length;
    return result;
  });
}
function marks(frame) {
  let standing = 10;
  return frame.map(pins => {
    const mark = pins === 10 ? 'X' : pins === standing ? '/' : pins === 0 ? '–' : String(pins);
    standing -= pins;
    if (standing === 0) standing = 10;
    return mark;
  }).join(' ');
}
function render() {
  const scores = totals();
  $('frames').replaceChildren(...frames.map((frame,i) => {
    const el = document.createElement('div');
    el.className = 'frame' + (i === current && !complete ? ' active' : '');
    el.innerHTML = `<small>Frame ${i+1}</small><div class="rolls">${marks(frame) || '·'}</div><div class="frame-score">${scores[i] === null ? '…' : scores[i]}</div>`;
    return el;
  }));
  $('total').textContent = scores.filter(score => score !== null).at(-1) ?? 0;
  $('score-label').textContent = complete ? 'Final score' : 'Resolved score';
  $('status').textContent = complete ? 'Game complete' : `Frame ${current+1} · Roll ${frames[current].length+1}`;
  $('remaining').textContent = complete ? 'All ten frames played' : `${remaining} pins standing`;
  $('pins').max = remaining;
  $('pins').disabled = complete;
  $('roll-button').disabled = complete;
}
$('roll-form').addEventListener('submit', event => {
  event.preventDefault();
  const text = $('pins').value.trim(), pins = Number(text);
  if (complete) return;
  if (!text || !Number.isInteger(pins) || pins < 0 || pins > remaining) {
    $('message').textContent = `Enter a whole number from 0 to ${remaining}.`;
    return;
  }
  const frame = frames[current];
  frame.push(pins); remaining -= pins;
  if (current < 9) {
    if (pins === 10 || frame.length === 2) { current++; remaining = 10; }
  } else {
    complete = frame.length === 3 || (frame.length === 2 && frame[0]+frame[1] < 10);
    if (remaining === 0) remaining = 10;
  }
  render();
  $('message').textContent = complete ? `Game complete. Final score: ${$('total').textContent}.` : `Recorded ${pins} pins.`;
  if (!complete) { $('pins').focus(); $('pins').select(); }
});
$('reset').addEventListener('click', reset);
reset();
